create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select nullif(current_setting('request.jwt.claim.role', true),'') $$;
grant usage on schema auth to anon, authenticated, service_role;
grant usage on schema public to anon, authenticated, service_role;
create table public.cdr_drugs_unique (drug_brand text, drug_type text, drug_form text, drug_strength text, drug_class text, id uuid default gen_random_uuid() primary key);
create table public.ps_audit_log (id uuid default gen_random_uuid() not null, organisation_id uuid not null, table_name text not null, record_id uuid not null, action text not null, old_data jsonb, new_data jsonb, performed_by uuid, session_id uuid, performed_at timestamp with time zone default now(), ip_address inet);
create table public.ps_balance_check_items (id uuid default gen_random_uuid() primary key, session_id uuid not null, organisation_id uuid not null, drug_id uuid not null, ledger_id uuid not null, drug_brand text not null, drug_form text not null, drug_strength text not null, drug_class text not null, expected_balance numeric not null, actual_count numeric, status text default 'pending'::text not null, adjustment_amount numeric, adjustment_reason text, notes text, checked_by uuid, checked_at timestamp with time zone, register_entry_id uuid, created_at timestamp with time zone default now());
create table public.ps_balance_check_sessions (id uuid default gen_random_uuid() primary key, organisation_id uuid not null, started_at timestamp with time zone default now() not null, completed_at timestamp with time zone, status text default 'in_progress'::text not null, started_by uuid not null, completed_by uuid, notes text, total_registers integer default 0, checked_count integer default 0, discrepancy_count integer default 0, created_at timestamp with time zone default now());
create table public.ps_entry_annotations (id uuid default gen_random_uuid() primary key, entry_id uuid not null, organisation_id uuid not null, annotation_text text not null, annotation_type text default 'note'::text, created_by uuid not null, created_at timestamp with time zone default now());
create table public.ps_organisation_members (id uuid default gen_random_uuid() primary key, organisation_id uuid not null, user_id uuid not null, role text default 'dispenser'::text not null, permissions jsonb default '{}'::jsonb, status text default 'active'::text, is_locum boolean default false);
create table public.ps_register_entries (id uuid default gen_random_uuid() primary key, ledger_id uuid not null, organisation_id uuid not null, entry_number integer not null, register_type text not null, entry_type text not null, date_of_transaction date default CURRENT_DATE not null, notes text, source text default 'manual'::text not null, corrects_entry_id uuid, correction_reason text, scan_image_path text, entered_by uuid not null, session_id uuid, entered_at timestamp with time zone default now() not null, previous_entry_id uuid, ledger_lock_version integer not null, quantity_received numeric, quantity_deducted numeric, running_balance numeric, previous_balance numeric, transaction_type text, supplier_name text, invoice_number text, patient_name text, patient_address text, prescriber_name text, prescriber_address text, prescription_date date, prescription_image_path text, witness_name text, witness_role text, authorised_by text, pharmacist_name text, gphc_number text, rp_signed_in_at timestamp with time zone, rp_signed_out_at timestamp with time zone, return_patient_name text, return_drug_name text, return_drug_form text, return_drug_strength text, return_quantity numeric, return_reason text, return_received_by text, disposal_date date, disposal_witness text, disposal_method text, was_id_requested boolean default false, was_id_provided boolean default false, prescriber_registration text, return_person_role text, return_received_signature text, disposal_pharmacist_signature text, witness_signature text, return_parent_entry_id uuid, supplier_address text, collector_type text, collector_details text, unique(ledger_id, entry_number),
 constraint ps_register_entries_check1 CHECK (((register_type <> ALL (ARRAY['CD'::text, 'PRIVATE_CD'::text])) OR (entry_type = 'correction'::text) OR (entry_type = 'balance_check'::text) OR ((quantity_received IS NOT NULL) OR (quantity_deducted IS NOT NULL)))),
 constraint ps_register_entries_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['receipt'::text, 'supply'::text, 'return_to_supplier'::text, 'patient_return'::text, 'disposal'::text, 'correction'::text, 'transfer_in'::text, 'transfer_out'::text, 'balance_check'::text]))));
create table public.ps_register_ledgers (id uuid default gen_random_uuid() primary key, organisation_id uuid not null, register_type text not null, drug_id uuid, drug_name text, drug_form text, drug_strength text, drug_class text, current_balance numeric default 0, entry_count integer default 0 not null, lock_version integer default 0 not null, is_active boolean default true, created_at timestamp with time zone default now(), created_by uuid, UNIQUE NULLS NOT DISTINCT (organisation_id, register_type, drug_id));
create table public.ps_subscribed_registers (id uuid default gen_random_uuid() primary key, organisation_id uuid not null, drug_id uuid not null, drug_brand text not null, drug_form text not null, drug_strength text not null, drug_class text not null, drug_type text not null, created_at timestamp with time zone default now(), created_by uuid, unique(organisation_id, drug_id));
create table public.ps_user_profiles (id uuid primary key, full_name text not null, gphc_number text);
grant all on all tables in schema public to anon, authenticated, service_role;
do $$ declare t text; begin foreach t in array array['ps_register_entries','ps_register_ledgers','ps_subscribed_registers','ps_balance_check_items','ps_balance_check_sessions','ps_entry_annotations','ps_organisation_members','ps_user_profiles','cdr_drugs_unique'] loop execute format('alter table %I enable row level security', t); end loop; end $$;
create policy p on ps_organisation_members for select using (user_id = auth.uid());
create policy p on ps_user_profiles for select using (true);
create policy p on cdr_drugs_unique for select to authenticated using (true);
CREATE OR REPLACE FUNCTION public.ps_get_user_org_ids() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $f$ SELECT organisation_id FROM ps_organisation_members WHERE user_id = auth.uid() AND status = 'active'; $f$;
CREATE OR REPLACE FUNCTION public.ps_audit_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $f$ BEGIN INSERT INTO ps_audit_log (organisation_id, table_name, record_id, action, old_data, new_data, performed_by) VALUES (COALESCE(NEW.organisation_id, OLD.organisation_id), TG_TABLE_NAME, COALESCE(NEW.id, OLD.id), TG_OP, CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END, CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END, auth.uid()); RETURN COALESCE(NEW, OLD); END; $f$;
CREATE FUNCTION public.ps_prevent_entry_mutation() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN RAISE EXCEPTION 'Register entries are immutable. Cannot % on ps_register_entries.', TG_OP; END; $f$;
create trigger ps_entries_no_update before update on ps_register_entries for each row execute function ps_prevent_entry_mutation();
create trigger ps_entries_no_delete before delete on ps_register_entries for each row execute function ps_prevent_entry_mutation();
create trigger ps_audit_entries after insert on ps_register_entries for each row execute function ps_audit_trigger();
-- London policies as of 3 Nov 2026
create policy ps_entries_insert on ps_register_entries for insert with check (entered_by = auth.uid() and organisation_id in (select om.organisation_id from ps_organisation_members om where om.user_id = auth.uid() and om.status='active'));
create policy ps_entries_select on ps_register_entries for select using (organisation_id in (select om.organisation_id from ps_organisation_members om where om.user_id = auth.uid() and om.status='active'));
create policy ps_ledgers_insert on ps_register_ledgers for insert with check (organisation_id in (select om.organisation_id from ps_organisation_members om where om.user_id = auth.uid() and om.status='active'));
create policy ps_ledgers_select on ps_register_ledgers for select using (organisation_id in (select om.organisation_id from ps_organisation_members om where om.user_id = auth.uid() and om.status='active'));
create policy "Users can view own org subscribed registers" on ps_subscribed_registers for select using (organisation_id in (select organisation_id from ps_organisation_members where user_id = auth.uid()));
create policy "Users can insert own org subscribed registers" on ps_subscribed_registers for insert with check (organisation_id in (select organisation_id from ps_organisation_members where user_id = auth.uid()));
create policy "Users can delete own org subscribed registers" on ps_subscribed_registers for delete using (organisation_id in (select organisation_id from ps_organisation_members where user_id = auth.uid()));
create policy ps_balance_sessions_select on ps_balance_check_sessions for select using (organisation_id in (select ps_get_user_org_ids()));
create policy ps_balance_sessions_insert on ps_balance_check_sessions for insert with check (organisation_id in (select ps_get_user_org_ids()));
create policy ps_balance_sessions_update on ps_balance_check_sessions for update using (organisation_id in (select ps_get_user_org_ids()));
create policy ps_balance_items_select on ps_balance_check_items for select using (organisation_id in (select ps_get_user_org_ids()));
create policy ps_balance_items_insert on ps_balance_check_items for insert with check (organisation_id in (select ps_get_user_org_ids()));
create policy ps_balance_items_update on ps_balance_check_items for update using (organisation_id in (select ps_get_user_org_ids()));
create policy ps_annotations_select on ps_entry_annotations for select using (organisation_id in (select ps_get_user_org_ids()));
